(async()=>{
const root=document.querySelector('[data-gallery]');if(!root)return;
const stage=root.querySelector('.gallery-stage'),thumbs=root.querySelector('.thumbnails'),base=root.dataset.base;
const asset=p=>/^(https?:|data:|blob:)/.test(p)?p:`${base}/${p.replace(/^\//,'')}`;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let all;try{const r=await fetch(root.dataset.gallery);if(!r.ok)throw Error();all=await r.json();}catch{stage.innerHTML='<p class="load-error">The gallery could not load. Please try again later.</p>';return;}
let items=all,index=0,opener;
const dialog=document.createElement('dialog');dialog.setAttribute('aria-labelledby','modal-title');dialog.innerHTML='<div class="modal-head"><h2 id="modal-title"></h2><button type="button">Close ×</button></div><div class="modal-media"></div><p class="modal-caption"></p>';document.body.append(dialog);
const pause=node=>node.querySelectorAll('video').forEach(v=>v.pause());
function placeholder(g,n){const wrap=document.createElement('div');wrap.className='placeholder';const inner=document.createElement('div');inner.className='placeholder-inner';const num=document.createElement('span');num.className='media-index';num.textContent=String(n+1).padStart(2,'0');const title=document.createElement('strong');title.textContent=g.title;const note=document.createElement('small');note.textContent='MEDIA PLACEHOLDER · ORIGINAL FIGURE TO BE ADDED';inner.append(num,title,note);wrap.append(inner);return wrap;}
function media(g,n,expanded=false){if(!g.src||g.type==='placeholder')return placeholder(g,n);const video=['video','mp4','webm'].includes(g.type);const el=document.createElement(video?'video':'img');if(video){el.controls=true;el.playsInline=true;el.preload='metadata';if(g.poster)el.poster=asset(g.poster);el.setAttribute('aria-label',g.alt);}else{el.alt=g.alt;el.decoding='async';}if(g.type==='gif'&&reduced&&!expanded){if(g.poster){el.src=asset(g.poster);}else{const ph=placeholder(g,n);ph.querySelector('small').textContent='ANIMATION PAUSED · OPEN TO PLAY';return ph;}}else el.src=asset(g.src);el.addEventListener('error',()=>{const ph=placeholder(g,n);ph.querySelector('small').textContent='MEDIA UNAVAILABLE';el.replaceWith(ph);});return el;}
function open(g,button){opener=button;pause(stage);dialog.querySelector('h2').textContent=g.title;dialog.querySelector('.modal-caption').textContent=g.caption;dialog.querySelector('.modal-media').replaceChildren(media(g,index,true));dialog.showModal();dialog.querySelector('button').focus();}
dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{pause(dialog);dialog.querySelector('.modal-media').replaceChildren();opener?.focus();});
function render(){pause(stage);stage.replaceChildren();thumbs.replaceChildren();if(!items.length){stage.textContent='No media in this category.';return;}const g=items[index];const visual=media(g,index);if(['video','mp4','webm'].includes(g.type)&&g.src){stage.append(visual);const b=document.createElement('button');b.className='video-expand';b.textContent='Enlarge ↗';b.onclick=()=>open(g,b);stage.append(b);}else{const b=document.createElement('button');b.className='media-open';b.setAttribute('aria-label',`Enlarge ${g.title}`);b.append(visual);b.onclick=()=>open(g,b);stage.append(b);const hint=document.createElement('span');hint.className='expand-hint';hint.textContent='Click to enlarge ↗';stage.append(hint);}
root.querySelector('#gallery-label').textContent=g.label;root.querySelector('#gallery-title').textContent=g.title;root.querySelector('#gallery-caption').textContent=g.caption;root.querySelector('#gallery-project').href=`${base}/projects/${g.project}/`;root.querySelector('#gallery-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}`;
items.forEach((v,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(i===index));b.setAttribute('aria-label',`Show ${v.title}`);if(v.thumbnail){const im=document.createElement('img');im.src=asset(v.thumbnail);im.alt='';im.loading='lazy';b.append(im);}else{const num=document.createElement('span');num.className='thumb-number';num.textContent=String(i+1).padStart(2,'0');b.append(num);}const label=document.createElement('span');label.textContent=v.title;b.append(label);b.onclick=()=>{index=i;render();thumbs.children[i]?.focus();};thumbs.append(b);});root.querySelector('[data-prev]').disabled=items.length<2;root.querySelector('[data-next]').disabled=items.length<2;}
function move(d){if(items.length){index=(index+d+items.length)%items.length;render();}}
root.querySelector('[data-prev]').onclick=()=>move(-1);root.querySelector('[data-next]').onclick=()=>move(1);root.addEventListener('keydown',e=>{if(e.target.tagName==='VIDEO')return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const focus=e.target;move(e.key==='ArrowRight'?1:-1);if(!focus.isConnected)thumbs.children[index]?.focus();}});
let start;stage.addEventListener('touchstart',e=>{if(e.target.tagName==='VIDEO')return;start=[e.changedTouches[0].clientX,e.changedTouches[0].clientY];},{passive:true});stage.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start[0],dy=e.changedTouches[0].clientY-start[1];start=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy))move(dx<0?1:-1);},{passive:true});
new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)pause(root);})).observe(root);document.addEventListener('visibilitychange',()=>{if(document.hidden){pause(root);pause(dialog);}});
document.querySelector('#gallery-filter')?.addEventListener('change',e=>{items=e.target.value==='all'?all:all.filter(g=>g.category===e.target.value);index=0;render();});render();
})();
